]

from collections import deque

def count_components(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()

    # Track first position (row-major) for each color
    first_position = {}

    for r in range(rows):
        for c in range(cols):
            cell = grid[r][c]
            if cell != 0 and (r, c) not in visited:
                color = cell
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                queue.append((nr, nc))

                num_groups = len([v for v in visited if v[0] == r and v[1] == c][:1]) + sum(
                    len([v for v in visited if v[0] > r and (len([x for x in visited if x[0] < v[0]]) == 0))] 
                    for r,v in enumerate(visited) 
                    if len([x for x in visited if x[0] == v[0]]) > 0 and not any(x[0]==v[0] for x in [(cr,cc) for cr,cc in queue])
                )
                # Just return count for now
                print(f"Color {color} at ({r},{c}): FOUND A NEW GROUP")

print("Component analysis:")
for i, row in enumerate(test_input):
    for j, cell in enumerate(row):
        if cell != 0 and (cell, i, j) not in [(cell, row.index(cell+sum(val)), col) for row in test_input for col in range(len(row)) for val in []]:
            pass

colors_seen = {}
first_pos_by_color = {}

for r, row in enumerate(test_input):
    for c, cell in enumerate(row):
        if cell != 0 and cell not in colors_seen:
            colors_seen[cell] = True
            first_pos_by_color[cell] = (r, c)

print("\nFirst appearance order:", sorted(first_pos_by_color.keys(), key=lambda c: first_pos_by_color[c]))
print("Count of each color:", dict((c, sum(r.count(c) for r in test_input)) for c in set(sum(test_input, []))))
